CREATE TABLE IF NOT EXISTS pipeline_runs (run_id BIGSERIAL PRIMARY KEY, source_file TEXT NOT NULL, load_type TEXT NOT NULL, started_at TIMESTAMPTZ DEFAULT now(), ended_at TIMESTAMPTZ, status TEXT NOT NULL CHECK(status IN ('RUNNING','SUCCESS','FAILED')), records_extracted INT DEFAULT 0, records_loaded INT DEFAULT 0, records_rejected INT DEFAULT 0, error_message TEXT);
CREATE TABLE IF NOT EXISTS pipeline_checkpoint (source_file TEXT PRIMARY KEY, last_batch_done INT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS staging_records (id BIGSERIAL PRIMARY KEY, run_id BIGINT REFERENCES pipeline_runs(run_id), batch_no INT NOT NULL, source_row TEXT, account_id TEXT, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS clean_records (account_id TEXT PRIMARY KEY, lead_owner TEXT, first_name TEXT, last_name TEXT, company TEXT, phone_1 TEXT, phone_2 TEXT, email_1 TEXT, email_2 TEXT, website TEXT, source TEXT, deal_stage TEXT, notes TEXT, updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS final_leads (account_id TEXT PRIMARY KEY REFERENCES clean_records(account_id), full_name TEXT, company TEXT, email TEXT, source TEXT, deal_stage TEXT, updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS rejected_records (id BIGSERIAL PRIMARY KEY, run_id BIGINT REFERENCES pipeline_runs(run_id), source_row TEXT, reason TEXT, rejected_at TIMESTAMPTZ DEFAULT now());
